-- BrandKraf — BM translation batch 14: FULL-DEPTH (5 articles, net-new). Run AFTER blog-i18n-migration.sql.
-- Faithful, section-for-section translations of the English articles. Content dollar-quoted ($ms$...$ms$).

update public.blog_posts set
  title_ms = 'Tip Fotografi Produk (Menggunakan Hanya Telefon Anda)',
  excerpt_ms = 'Foto produk yang hebat menjual — dan anda tidak perlukan kamera profesional. Pelajari tip pencahayaan, latar belakang, sudut, dan penyuntingan untuk merakam imej produk yang menghentikan susur pada telefon anda.',
  content_ms = $ms$<p>Dalam e-dagang, foto anda ialah produk anda — pelanggan tidak boleh menyentuh atau mencuba, jadi imej melakukan semua pujukan. Berita baiknya: anda boleh merakam foto produk yang kelihatan profesional dengan hanya telefon anda. Inilah caranya.</p>
<blockquote>Dalam talian, orang tidak membeli produk anda — mereka membeli foto anda tentangnya. Jadikan foto itu berbaloi dibeli.</blockquote>
<h2>Cahaya ialah segala-galanya</h2>
<p>Pencahayaan yang lembut dan sekata ialah perbezaan antara amatur dan profesional. Cahaya semula jadi berhampiran tingkap besar berfungsi dengan cantik dan tidak berkos apa-apa. Elakkan cahaya matahari langsung yang keras dan pencahayaan bercampur. Peresap ringkas atau softbox berbajet membawanya lebih jauh — tetapi mula dengan tingkap.</p>
<h2>Pastikan latar belakang bersih</h2>
<p>Latar belakang yang bersih dan tidak berselerak mengekalkan perhatian pada produk. Latar putih atau neutral yang polos (walaupun sehelai kertas atau papan poster) kelihatan profesional dan mesra pasaran. Kekonsistenan merentasi katalog anda juga mengukuhkan jenama anda.</p>
<h2>Rakam pelbagai sudut dan butiran</h2>
<p>Pelanggan mahu melihat produk sepenuhnya. Tangkap depan, belakang, sisi, dan tampak dekat butiran dan tekstur penting. Lebih yakin pembeli boleh membayangkan item itu, lebih berkemungkinan mereka membeli — dan lebih sedikit pemulangan yang anda dapat.</p>
<h2>Tunjukkan skala dan konteks</h2>
<p>Sertakan tangkapan yang menunjukkan saiz dan penggunaan dunia sebenar — produk dalam tangan, dipakai, atau dalam persekitarannya. Imej gaya hidup membantu pembeli membayangkan memilikinya dan selalunya menukar lebih baik daripada tangkapan katalog polos sahaja.</p>
<h2>Sunting untuk ketepatan, bukan penipuan</h2>
<p>Penyuntingan ringan — meluruskan, mencerahkan, dan membetulkan warna — menjadikan foto menonjol. Tetapi pastikan produk tepat; foto mengelirukan membawa kepada pemulangan dan ulasan buruk. Aplikasi telefon percuma mengendalikan kebanyakan suntingan dengan baik.</p>
<h2>Kekal konsisten</h2>
<p>Gaya yang konsisten — pencahayaan, latar belakang, dan pembingkaian yang sama — menjadikan kedai anda kelihatan profesional dan boleh dipercayai. Tetapkan templat ringkas dan guna semula untuk setiap produk. Ini berpasangan dengan sempurna dengan <a href="/ms/blog/how-to-batch-create-content">berkelompok</a> penggambaran anda.</p>
<h2>Soalan lazim</h2>
<h3>Adakah saya perlukan kamera profesional?</h3>
<p>Tidak. Telefon moden merakam foto produk yang sangat baik. Laburkan dalam pencahayaan dan latar belakang bersih sebelum kamera.</p>
<h3>Apa latar belakang terbaik untuk foto produk?</h3>
<p>Putih atau neutral yang bersih untuk tangkapan katalog; persekitaran gaya hidup untuk konteks. Kekonsistenan paling penting.</p>
<h3>Berapa foto setiap produk?</h3>
<p>Beberapa — pelbagai sudut, tampak dekat butiran, dan sekurang-kurangnya satu tangkapan gaya hidup atau dalam penggunaan.</p>
<h3>Aplikasi penyuntingan apa patut saya guna?</h3>
<p>Aplikasi penyuntingan telefon percuma sudah memadai untuk kecerahan, warna, dan pemangkasan. Pastikan suntingan tepat kepada produk sebenar.</p>
<p>BrandKraf mencipta visual produk dan jenama yang menjual. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/portfolio/ugc-content-creation">perkhidmatan kandungan</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'product-photography-tips';

update public.blog_posts set
  title_ms = 'Cara Menulis Penerangan Produk yang Menjual',
  excerpt_ms = 'Penerangan produk yang baik lebih daripada menyenaraikan ciri — ia menjual. Pelajari cara menulis penerangan yang menyerlahkan manfaat, membina keinginan, dan menukar penyemak imbas menjadi pembeli.',
  content_ms = $ms$<p>Kebanyakan penerangan produk ialah senarai spesifikasi yang membosankan yang tiada siapa membaca. Yang hebat melakukan sesuatu yang berbeza: ia menjual. Ia menukar penyemak imbas yang ingin tahu menjadi pembeli yang yakin. Inilah cara menulis penerangan produk yang benar-benar menukar.</p>
<blockquote>Ciri memberitahu. Manfaat menjual. Kisah membuatkan orang membeli.</blockquote>
<h2>Ketahui untuk siapa anda menulis</h2>
<p>Sebelum menulis, bayangkan pelanggan ideal anda dan apa yang mereka ambil berat. Penerangan yang bercakap terus kepada keinginan dan kebimbangan mereka berhubung jauh lebih baik daripada salinan generik. Tulis kepada seorang, bukan "semua orang".</p>
<h2>Pimpin dengan manfaat, bukan hanya ciri</h2>
<p>Jangan hanya kata apa produk itu — kata apa yang ia lakukan untuk pelanggan. "Kalis air" ialah ciri; "kekal kering menembusi hujan lebat" ialah manfaat. Terjemahkan setiap spesifikasi kepada nilai yang disampaikannya. Ini teras <a href="/ms/blog/marketing-copywriting-that-sells">penulisan salinan</a>.</p>
<h2>Jadikan ia mudah diimbas</h2>
<p>Pembeli mengimbas. Gunakan perenggan pendek, poin peluru untuk ciri utama, dan format yang jelas supaya orang boleh menyerap perkara penting dengan pantas. Dinding teks dilangkau; susun atur yang mudah diimbas dibaca.</p>
<h2>Gunakan bahasa deria dan khusus</h2>
<p>Perkataan yang khusus dan jelas membina keinginan dan kepercayaan. Daripada "berkualiti tinggi", huraikan rasa lembut, warna kaya, dimensi tepat. Butiran konkrit menjadikan produk nyata dalam fikiran pembeli dan mengurangkan ketidakpastian.</p>
<h2>Jawab bantahan dan soalan</h2>
<p>Tangani keraguan yang menghentikan pembelian — saiz, bahan, keserasian, penjagaan, penghantaran. Menjawab soalan di dalam penerangan menghapuskan geseran dan mengurangkan pemulangan serta mesej sokongan.</p>
<h2>Sertakan kata kunci untuk carian</h2>
<p>Sertakan secara semula jadi perkataan yang dicari pembeli — di pasaran dan Google. Kata kunci yang baik membantu produk anda ditemui tanpa mengorbankan kebolehbacaan. Lihat <a href="/ms/blog/ecommerce-seo-guide">panduan SEO e-dagang</a> kami.</p>
<h2>Soalan lazim</h2>
<h3>Berapa panjang penerangan produk patut?</h3>
<p>Cukup panjang untuk menjual dan menjawab soalan utama, cukup pendek untuk kekal mudah diimbas. Pimpin dengan manfaat; tambah butiran di bawah.</p>
<h3>Patutkah saya gunakan penerangan pengeluar?</h3>
<p>Elakkan menyalinnya — penerangan pendua menjejaskan SEO dan jarang menjual dengan baik. Tulis versi anda sendiri yang berfokuskan manfaat.</p>
<h3>Adakah kata kunci benar-benar penting dalam penerangan?</h3>
<p>Ya, untuk carian pasaran dan Google. Sertakannya secara semula jadi tanpa penyumbatan kata kunci.</p>
<h3>Apa kesilapan terbesar?</h3>
<p>Menyenaraikan hanya ciri tanpa manfaat, dan menulis salinan generik yang boleh menerangkan mana-mana produk.</p>
<p>BrandKraf menulis salinan yang menukar untuk jenama Malaysia. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/portfolio/social-media-management">perkhidmatan kandungan</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'how-to-write-product-descriptions';

update public.blog_posts set
  title_ms = 'SEO E-dagang: Dapatkan Produk Anda Ditemui di Google',
  excerpt_ms = 'SEO e-dagang membawa trafik percuma berniat tinggi ke kedai anda. Pelajari cara mengoptimumkan halaman produk dan kategori untuk mendapat kedudukan di Google dan menangkap pembeli yang mencari untuk membeli.',
  content_ms = $ms$<p>Iklan berbayar berhenti pada saat anda berhenti membayar. SEO terus berfungsi — membawa pembeli percuma berniat tinggi ke kedai anda bulan demi bulan. Untuk e-dagang, mendapat kedudukan di Google untuk carian produk yang betul ialah salah satu aset jangka panjang paling bernilai yang boleh anda bina.</p>
<blockquote>Seseorang yang mencari "beli X dalam talian Malaysia" sudah bersedia berbelanja. SEO e-dagang meletakkan anda di hadapan mereka secara percuma.</blockquote>
<h2>Sasarkan kata kunci niat pembeli</h2>
<p>Fokus pada kata kunci yang menandakan niat pembelian — nama produk, "beli", "harga", "dalam talian", dan istilah kategori anda. Pencari ini hampir membeli, yang menjadikan mendapat kedudukan untuk mereka jauh lebih bernilai daripada trafik generik. Bina atas <a href="/ms/blog/seo-basics-rank-on-google">panduan asas SEO</a> kami.</p>
<h2>Optimumkan halaman produk</h2>
<p>Setiap halaman produk patut mempunyai tajuk dan penerangan yang kaya kata kunci dan unik, salinan produk asli (bukan disalin daripada pengeluar), teks alt imej deskriptif, dan spesifikasi yang jelas. Halaman yang unik dan berguna mendapat kedudukan; yang nipis atau pendua tidak.</p>
<h2>Jangan abaikan halaman kategori</h2>
<p>Halaman kategori selalunya mendapat kedudukan untuk istilah luas dan volum tinggi seperti "kasut lari lelaki". Beri ia perenggan pengenalan yang pendek dan berguna dengan kata kunci relevan, dan strukturkannya dengan jelas. Ia kerap peluang SEO terbesar anda.</p>
<h2>Jadikan kedai anda pantas dan mesra mudah alih</h2>
<p>Kelajuan dan pengalaman mudah alih ialah faktor kedudukan dan faktor penukaran. Mampatkan imej, pilih pengehosan pantas, dan pastikan segalanya berfungsi lancar di telefon — tempat kebanyakan membeli-belah Malaysia berlaku.</p>
<h2>Tambah data berstruktur dan ulasan</h2>
<p>Penanda skema produk boleh menunjukkan harga, ketersediaan, dan penarafan bintang terus dalam hasil carian, meningkatkan klik. Ulasan pelanggan tulen menambah kandungan segar dan isyarat kepercayaan. Kedua-duanya membantu anda menonjol di halaman hasil.</p>
<h2>Perolehi pautan dan bina kandungan</h2>
<p>Pautan dan kandungan berguna membina kewibawaan yang menaikkan keseluruhan kedai anda. Kandungan blog (panduan membeli, cara buat) menarik pautan dan mendapat kedudukan untuk carian peringkat penyelidikan yang memberi makan halaman produk anda. SEO berkompaun dari masa ke masa — mula sekarang.</p>
<h2>Soalan lazim</h2>
<h3>Berapa lama SEO e-dagang mengambil masa?</h3>
<p>Biasanya berbulan-bulan untuk membina momentum, tetapi ia berkompaun menjadi trafik percuma yang tahan lama — tidak seperti iklan yang berhenti apabila anda berhenti.</p>
<h3>Patutkah saya menulis penerangan produk unik untuk SEO?</h3>
<p>Ya. Salinan pengeluar pendua menjejaskan kedudukan. Penerangan asli yang dipimpin manfaat mendapat kedudukan dan menukar lebih baik.</p>
<h3>Adakah halaman kategori penting untuk SEO?</h3>
<p>Sangat — ia selalunya mendapat kedudukan untuk istilah volum tinggi. Tambah pengenalan yang berguna dan kaya kata kunci serta struktur yang jelas.</p>
<h3>Apa itu skema produk?</h3>
<p>Data berstruktur yang membolehkan Google menunjukkan harga, stok, dan penarafan dalam hasil, meningkatkan keterlihatan dan klik.</p>
<p>BrandKraf membantu kedai Malaysia mendapat kedudukan dan menjual. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/guides/seo">panduan SEO</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'ecommerce-seo-guide';

update public.blog_posts set
  title_ms = 'Cara Mendapat Lebih Banyak Ulasan Pelanggan (dan Mengapa Ia Menjual)',
  excerpt_ms = 'Ulasan ialah pemasaran paling meyakinkan yang anda tidak tulis. Pelajari cara mendapat lebih banyak ulasan pelanggan secara beretika dan menggunakannya untuk meningkatkan kepercayaan, penukaran, dan SEO.',
  content_ms = $ms$<p>Sebelum membeli, kebanyakan orang menyemak ulasan — mereka mempercayai pelanggan lain jauh lebih daripada pemasaran anda. Ulasan ialah bukti sosial percuma yang berkuasa yang meningkatkan penukaran, kedudukan, dan kepercayaan. Inilah cara mendapat lebih banyak, dengan cara yang betul.</p>
<blockquote>Pelanggan anda menjual untuk anda lebih meyakinkan daripada apa-apa yang boleh anda katakan tentang diri anda sendiri.</blockquote>
<h2>Mengapa ulasan sangat penting</h2>
<p>Ulasan mengurangkan risiko yang dirasai pembeli, meningkatkan kadar penukaran, menambah baik SEO tempatan dan produk, dan menyediakan kandungan segar yang dipercayai. Produk atau perniagaan dengan ulasan yang kukuh menjual lebih banyak — dan kekurangan ulasan secara senyap merugikan anda jualan.</p>
<h2>Cuma tanya — pada masa yang betul</h2>
<p>Cara paling mudah mendapat ulasan ialah bertanya. Waktukannya untuk ketika kepuasan paling tinggi — selepas penghantaran, selepas pengalaman positif, atau selepas pembelian berulang. Permintaan yang sopan dan tepat masanya mendapat bilangan respons yang mengejutkan.</p>
<h2>Jadikan ia tanpa usaha</h2>
<p>Setiap langkah tambahan kehilangan ulasan. Hantar pautan terus, kekalkan proses kepada beberapa ketik, dan beritahu orang lebih kurang berapa lama ia mengambil masa. Lebih mudah anda menjadikannya, lebih banyak ulasan yang anda dapat.</p>
<h2>Automasikan permintaan</h2>
<p>Sediakan e-mel atau mesej WhatsApp automatik selepas pembelian atau penghantaran untuk meminta ulasan. Automasi bermakna anda tidak pernah lupa dan ia berskala tanpa usaha — lihat <a href="/ms/blog/email-marketing-automation-guide">panduan automasi e-mel</a> kami.</p>
<h2>Balas setiap ulasan</h2>
<p>Membalas — kepada ulasan positif dan negatif — menunjukkan anda ambil berat dan membina kepercayaan dengan semua orang yang membaca. Kendalikan kritikan dengan tenang dan membantu; ulasan negatif yang dikendalikan dengan baik boleh mengkagumkan lebih daripada yang memuji. Lihat <a href="/ms/blog/handling-negative-comments-social-media">mengendalikan komen negatif</a>.</p>
<h2>Tonjolkan ulasan anda</h2>
<p>Jangan biarkan ulasan tidak dilihat. Paparkannya di halaman produk, laman web anda, dan media sosial. Menukar ulasan menjadi kandungan menggandakan kuasa jualannya dan mengukuhkan kepercayaan pada saat keputusan.</p>
<h2>Soalan lazim</h2>
<h3>Bagaimana saya minta ulasan tanpa mengganggu?</h3>
<p>Tanya sekali, dengan sopan, pada saat kepuasan tinggi, dan jadikan ia mudah. Satu permintaan yang tepat masanya jarang mengganggu.</p>
<h3>Bolehkah saya tawarkan insentif untuk ulasan?</h3>
<p>Berhati-hati — sesetengah platform melarang ulasan berinsentif, dan ia mesti sentiasa jujur. Selalunya permintaan mudah sudah memadai.</p>
<h3>Bagaimana saya kendalikan ulasan buruk?</h3>
<p>Balas dengan tenang, akui isu itu, dan tawarkan untuk membetulkannya. Semua orang yang memerhati menilai respons anda lebih daripada aduan itu.</p>
<h3>Di mana ulasan patut muncul?</h3>
<p>Di halaman produk, Profil Perniagaan Google anda, dan media sosial — di mana sahaja pembeli memutuskan sama ada hendak mempercayai anda.</p>
<p>BrandKraf membantu jenama membina kepercayaan dan reputasi. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/portfolio/social-media-management">perkhidmatan media sosial</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'get-more-customer-reviews';

update public.blog_posts set
  title_ms = 'Cara Menjalankan Jualan atau Promosi Dalam Talian yang Menguntungkan',
  excerpt_ms = 'Jualan memacu hasil — atau menghakis margin anda. Pelajari cara merancang dan menjalankan promosi dalam talian yang meningkatkan jualan tanpa melatih pelanggan untuk hanya membeli semasa diskaun.',
  content_ms = $ms$<p>Dilakukan dengan betul, jualan atau promosi mencipta lonjakan hasil dan pelanggan baharu. Dilakukan dengan salah, ia melatih pelanggan untuk menunggu diskaun dan secara senyap memusnahkan margin anda. Inilah cara menjalankan promosi yang benar-benar mengembangkan perniagaan anda.</p>
<blockquote>Promosi yang baik mencipta urgensi dan pelanggan baharu. Yang buruk hanya memberikan margin yang anda akan peroleh juga.</blockquote>
<h2>Mula dengan matlamat yang jelas</h2>
<p>Ketahui mengapa anda menjalankan jualan: menghabiskan stok lama, memperoleh pelanggan baharu, mencapai sasaran hasil, atau memberi ganjaran kepada pembeli setia. Matlamat membentuk tawaran, penonton, dan cara anda mengukur kejayaan. Jualan tanpa matlamat hanyalah margin yang hilang.</p>
<h2>Pilih tawaran yang betul</h2>
<p>Tawaran berbeza memenuhi matlamat berbeza — peratus diskaun, bundle, penghantaran percuma, beli-satu-dapat-satu, atau hadiah dengan pembelian. Bundle dan penghantaran percuma selalunya melindungi margin lebih baik daripada diskaun peratus yang mendalam. Pilih mekanik yang sesuai dengan matlamat dan ekonomi anda.</p>
<h2>Cipta urgensi sebenar</h2>
<p>Urgensi memacu tindakan. Tawaran masa terhad, kiraan detik, dan kuantiti terhad menolak pembeli teragak-agak untuk bertindak sekarang. Tarikh jualan mega Malaysia (9.9, 11.11, 12.12) dan musim perayaan datang dengan urgensi terbina dalam — rancang sekitarnya; lihat <a href="/ms/blog/shopee-lazada-ads-malaysia">panduan iklan pasaran</a> kami.</p>
<h2>Promosikan merentasi setiap saluran</h2>
<p>Jualan hanya berfungsi jika orang tahu. Promosikannya melalui e-mel, media sosial, iklan, sepanduk laman web anda, dan WhatsApp. Bina jangkaan sebelum, tolak kuat semasa, dan buat susulan selepas. Promosi pelbagai saluran memaksimumkan jangkauan.</p>
<h2>Sediakan kedai dan stok anda</h2>
<p>Lonjakan trafik mendedahkan kelemahan. Pastikan stok, kelajuan laman, pembayaran, dan pemenuhan anda boleh mengendalikan volum. Tiada apa yang membazir promosi seperti laman yang terhempas atau produk terlaris kehabisan tanpa rancangan.</p>
<h2>Lindungi margin dan jenama anda</h2>
<p>Jalankan jualan dengan niat, bukan sentiasa — diskaun kerap menghakis kedua-dua margin dan nilai jenama, dan mengajar pelanggan untuk tidak pernah membayar harga penuh. Gunakan promosi secara strategik, dan bersandar pada nilai dan kesetiaan pada masa lain. Lihat <a href="/ms/blog/customer-retention-loyalty-marketing">pengekalan pelanggan</a>.</p>
<h2>Soalan lazim</h2>
<h3>Berapa kerap saya patut menjalankan jualan?</h3>
<p>Secara berhemat dan strategik. Diskaun berterusan menghakis margin dan melatih pelanggan untuk menunggu. Kaitkan jualan dengan matlamat jelas dan tarikh utama.</p>
<h3>Apa jenis tawaran yang terbaik?</h3>
<p>Ia bergantung pada matlamat anda — bundle dan penghantaran percuma melindungi margin; diskaun peratus memacu urgensi. Padankan tawaran dengan objektif.</p>
<h3>Bagaimana saya promosikan jualan?</h3>
<p>Merentasi e-mel, sosial, iklan, WhatsApp, dan laman anda — dengan jangkaan sebelum, urgensi semasa, dan susulan selepas.</p>
<h3>Bagaimana saya kekalkan jualan menguntungkan?</h3>
<p>Tetapkan matlamat, pilih tawaran mesra margin, sediakan stok dan pemenuhan, dan elakkan terlebih diskaun. Ukur keuntungan sebenar, bukan hanya hasil.</p>
<p>BrandKraf merancang dan menjalankan promosi yang mengembangkan jenama Malaysia. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/portfolio/paid-advertising">perkhidmatan iklan</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'online-sale-promotion-strategy';
